public static class MouseButtonsChecks {
 static readonly BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
 static int checks,layouts;
 static void Check(bool good,string label){checks++;if(!good)throw new Exception(label);}
 static void Near(double actual,double expected,string label){Check(Math.Abs(actual-expected)<0.01,label+" actual="+actual+" expected="+expected);}
 static object Call(MainWindow window,string name,params object[] args){return typeof(MainWindow).GetMethod(name,Hidden).Invoke(window,args??new object[]{null});}
 static object Field(MainWindow window,string name){return typeof(MainWindow).GetField(name,Hidden).GetValue(window);}
 static void Set(MainWindow window,string name,object value){typeof(MainWindow).GetField(name,Hidden).SetValue(window,value);}
 static Dictionary<string,object> Map(params object[] items){var value=new Dictionary<string,object>();for(int i=0;i<items.Length;i+=2)value.Add((string)items[i],items[i+1]);return value;}
 static Dictionary<string,object> Fixture(int pid=7548){
  string[] targets=MouseButtonsUiFacts.MouseFunctions.Concat(new[]{"KeyA","ShiftMode","MouseProfile","KeyDisabled"}).ToArray();var normal=new Dictionary<string,object>();var shifted=new Dictionary<string,object>();string[] defaults={"MouseClickLeft","MouseClickRight","MouseClickMiddle","MouseLeftBackward","MouseLeftForward","MouseDPISwitch","MouseScrollUp","MouseScrollDown"};
  for(int i=0;i<MouseButtonsUiFacts.Sources.Length;i++){string source=MouseButtonsUiFacts.Sources[i];normal.Add(source,Map("target",defaults[i],"targetCode",MouseButtonsUiFacts.TargetCode(defaults[i]).Value));shifted.Add(source,Map("target","MouseClickRight","targetCode",497));}
  return Map("kind","mouse","deviceId","hid-0123456789abcdef","pid",pid,"connected",true,"online",true,"readbackConfirmed",true,"capturedAt","10:00:00","readCapabilities",new[]{"buttonBindings","shiftButtonBindings"},"setCapabilities",new[]{"buttonBinding"},"settingOptions",Map("buttonSources",MouseButtonsUiFacts.Sources,"buttonTargets",targets),"snapshot",Map("modelPid",pid,"activeProfile",0,"profileCount",1,"profileInformationUnconfirmed",false,"buttonBindings",normal,"shiftButtonBindings",shifted));
 }
 static Dictionary<string,object> Copy(Dictionary<string,object> source){var json=new JavaScriptSerializer();return json.Deserialize<Dictionary<string,object>>(json.Serialize(source));}
 static Dictionary<string,object> Snapshot(Dictionary<string,object> state){return (Dictionary<string,object>)state["snapshot"];}
 static Dictionary<string,object> Binding(Dictionary<string,object> state,string source,bool shift=false){return (Dictionary<string,object>)((Dictionary<string,object>)Snapshot(state)[shift?"shiftButtonBindings":"buttonBindings"])[source];}
 static IEnumerable<T> Logical<T>(DependencyObject root)where T:DependencyObject{if(root is T)yield return (T)root;foreach(object child in LogicalTreeHelper.GetChildren(root)){var item=child as DependencyObject;if(item==null)continue;foreach(T found in Logical<T>(item))yield return found;}}
 static T Tagged<T>(DependencyObject root,string tag)where T:FrameworkElement{return Logical<T>(root).Single(item=>Object.Equals(item.Tag,tag));}
 static void Pump(FrameworkElement root){root.UpdateLayout();Dispatcher.CurrentDispatcher.Invoke(new Action(()=>{}),DispatcherPriority.Background);root.UpdateLayout();}
 static void Measure(FrameworkElement root,double width,double height){root.Measure(new Size(width,height));root.Arrange(new Rect(0,0,width,height));Pump(root);}
 static void Click(Button button){button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static string Value(object option){return Convert.ToString(option.GetType().GetProperty("Value").GetValue(option,null));}
 static string Name(object option){return Convert.ToString(option.GetType().GetProperty("Name").GetValue(option,null));}
 static bool Enabled(object option){return (bool)option.GetType().GetProperty("Enabled").GetValue(option,null);}
 static MouseButtonsDraft Draft(MainWindow window){return (MouseButtonsDraft)Field(window,"mouseButtonsDraft");}
 static Dictionary<string,Dictionary<string,object>> States(MainWindow window){return (Dictionary<string,Dictionary<string,object>>)Field(window,"gearStates");}
 static FrameworkElement Build(MainWindow window,Dictionary<string,object> state,double width=1246){States(window).Clear();if(state!=null)States(window)["mouse"]=state;var body=new StackPanel();Call(window,"OriginalMouseButtonsPage",body,state);Measure(body,width,650);return body;}
 static void NoNative(MainWindow window){Check(!window.IsVisible&&PresentationSource.FromVisual(window)==null,"owner has no native presentation source");Check(!((WorkerClient)Field(window,"gearWorker")).Running,"no gear worker or GET/SET");Check(((Dictionary<string,WorkerClient>)Field(window,"sdkWorkers")).Count==0,"no SDK worker");}

 static void Facts(){
  foreach(int pid in new[]{7546,7548})foreach(bool shift in new[]{false,true})foreach(string source in MouseButtonsUiFacts.Sources){var state=Fixture(pid);var observed=MouseButtonsUiFacts.Read(state,source,shift);Check(observed.IdentityConfirmed&&observed.SourceAvailable&&observed.BindingKnown,"confirmed exact model and independently read binding");Check(observed.Shift==shift&&observed.TargetCode.HasValue,"false Shift and exact native code are retained");}
  foreach(string flag in new[]{"online","connected","readbackConfirmed"})foreach(object invalid in new object[]{false,null,"true",1,0}){var state=Fixture();state[flag]=invalid;Check(!MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown,"strict identity flag: "+flag);}
  foreach(object invalid in new object[]{null,0,"7548",7548.0,true,7489,7588,7547}){var state=Fixture();state["pid"]=invalid;Check(!MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown,"PID cannot be coerced or inferred");state=Fixture();Snapshot(state)["modelPid"]=invalid;Check(!MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown,"snapshot model must match exact identity");}
  foreach(string invalid in new[]{null,"","hid-0123456789abcde","hid-0123456789abcdef-7588","HID-0123456789ABCDEF","hid-0123456789abcdef ","hid-0123456789abcdeg"}){var state=Fixture();state["deviceId"]=invalid;Check(!MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown,"invalid stable HID identity rejected");}
  var suffixed=Fixture();suffixed["deviceId"]="hid-0123456789abcdef-7548";Check(MouseButtonsUiFacts.Read(suffixed,"leftButton",false).BindingKnown,"exact paired model suffix is accepted");
  foreach(string source in new[]{null,"","LeftButton","leftButton ","rawCode"})Check(!MouseButtonsUiFacts.Read(Fixture(),source,false).SourceAvailable,"unknown source never gains a physical button");
  foreach(string missing in new[]{"buttonBindings","shiftButtonBindings"}){var state=Fixture();state["readCapabilities"]=new[]{missing=="buttonBindings"?"shiftButtonBindings":"buttonBindings"};Check(!MouseButtonsUiFacts.Read(state,"leftButton",missing=="shiftButtonBindings").BindingKnown,"each binding bank needs its own GET capability");Check(MouseButtonsUiFacts.Read(state,"leftButton",missing!="shiftButtonBindings").BindingKnown,"missing one bank does not erase the other bank");}
  foreach(object invalid in new object[]{null,"496",496.0,true,-1,65536}){var state=Fixture();Binding(state,"leftButton")["targetCode"]=invalid;Check(!MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown,"raw target code must be valid typed integer");}
  var zero=Fixture();Binding(zero,"leftButton")["targetCode"]=0;Binding(zero,"leftButton")["target"]=null;var rawZero=MouseButtonsUiFacts.Read(zero,"leftButton",false);Check(rawZero.TargetCode==0&&!rawZero.BindingKnown,"raw zero preserved without inventing a default target");
  var mismatch=Fixture();Binding(mismatch,"leftButton")["targetCode"]=497;Check(!MouseButtonsUiFacts.Read(mismatch,"leftButton",false).BindingKnown,"name/code disagreement rejected");
  foreach(object invalid in new object[]{null,"buttonBinding",new object[]{1,true},new string[0]}){var state=Fixture();state["setCapabilities"]=invalid;var read=MouseButtonsUiFacts.Read(state,"leftButton",false);Check(read.BindingKnown&&!MouseButtonsUiFacts.CanChooseMouse(state,read),"read-only mapping remains visible without setter capability");}
  foreach(string invalid in new[]{null,""," ",new string('x',129)}){var state=Fixture();state["capturedAt"]=invalid;Check(MouseButtonsUiFacts.Read(state,"leftButton",false).BindingKnown&&!MouseButtonsUiFacts.CanChooseMouse(state,MouseButtonsUiFacts.Read(state,"leftButton",false)),"missing capture identity blocks editing, not observed readout");}
  var baseline=Fixture();var observation=MouseButtonsUiFacts.Read(baseline,"leftButton",false);var draft=new MouseButtonsDraft{DeviceId=observation.DeviceId,CapturedAt=observation.CapturedAt,SelectedButton="leftButton",Shift=false,BaselineTarget=observation.Target,BaselineCode=observation.TargetCode,Target="MouseClickRight",Type="mouse",Dirty=true};var request=MouseButtonsUiFacts.Command(baseline,draft);Check(request!=null&&request.Count==3&&(bool)request["shift"]==false,"regular bank false survives command construction");
  foreach(string target in MouseButtonsUiFacts.MouseFunctions.Where(name=>name!=draft.BaselineTarget)){draft.Target=target;Check(MouseButtonsUiFacts.Command(baseline,draft)!=null,"ten source-confirmed mouse functions can form single-field commands");}
  foreach(string target in new[]{"KeyA","ShiftMode","MouseProfile","KeyDisabled","Macro","rawCode",""}){draft.Target=target;Check(MouseButtonsUiFacts.Command(baseline,draft)==null,"unimplemented or unlisted main function cannot emit a command");}
  draft.Target="MouseClickRight";foreach(string type in new[]{"keyboard","macro","media","windows","speedshift","armoury","text","screenshot","unknown"}){draft.Type=type;Check(MouseButtonsUiFacts.Command(baseline,draft)==null,"unimplemented category cannot emit a mouse command");}
  draft.Type="mouse";draft.Dirty=false;Check(MouseButtonsUiFacts.Command(baseline,draft)==null,"unmodified draft emits no command");draft.Dirty=true;draft.Target=draft.BaselineTarget;Check(MouseButtonsUiFacts.Command(baseline,draft)==null,"no-op target emits no command");
 }
 static void DraftsAndGates(MainWindow window){
  var state=Fixture();var root=Build(window,state);Click(Tagged<Button>(root,"sideKeyLeftForward"));var draft=Draft(window);Check(draft.SelectedButton=="sideKeyLeftForward"&&draft.Target=="MouseLeftForward"&&!draft.Dirty,"button selection captures getter but sends no command");
  var functions=Tagged<ComboBox>(root,"MouseButtons.Function");functions.SelectedItem=functions.Items.Cast<object>().Single(item=>Value(item)=="MouseClickRight");Check(draft.Dirty&&draft.Target=="MouseClickRight","function selection edits only local draft");Check((bool)Call(window,"MouseButtonsHasPendingDraft",state),"current dirty draft suppresses redundant page reread");Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"render-only blocks explicit apply");Call(window,"ApplyMouseButtonsDraftAsync",state,draft);
  Set(window,"render",false);Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"hardware consent defaults off independently of local editing");((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(true);Check((bool)Call(window,"MouseButtonsMayApply",state,draft),"explicit permission plus current binding permits only a dirty supported command");
  foreach(string flag in new[]{"busy","closing","mouseButtonsApplying"}){Set(window,flag,true);Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft)&&!(bool)Call(window,"MouseButtonsCanEdit",state,draft),"busy/closing/applying blocks edits and writes");string before=draft.Target;functions.SelectedItem=functions.Items.Cast<object>().Single(item=>Value(item)=="MouseScrollUp");Check(draft.Target==before&&Value(functions.SelectedItem)==before,"late busy gate prevents both draft and visible combo from changing");Click(Tagged<Button>(root,"rightButton"));Check(draft.SelectedButton=="sideKeyLeftForward","late busy gate prevents selection changes");Call(window,"ApplyMouseButtonsDraftAsync",state,draft);Set(window,flag,false);}
  var replacement=Copy(state);States(window)["mouse"]=replacement;Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"new same-ID session reference invalidates old editor callbacks");States(window)["mouse"]=state;state["capturedAt"]="10:00:01";Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"capture stamp mutation invalidates baseline");state["capturedAt"]="10:00:00";var oldSnapshot=Snapshot(state);state["snapshot"]=Copy(oldSnapshot);Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"snapshot reference replacement invalidates baseline");state["snapshot"]=oldSnapshot;Binding(state,"sideKeyLeftForward")["target"]="MouseClickLeft";Binding(state,"sideKeyLeftForward")["targetCode"]=496;Check(!(bool)Call(window,"MouseButtonsMayApply",state,draft),"in-place baseline mapping change invalidates dirty command");
  ((HardwareControlPolicy)Field(window,"hardwareControlPolicy")).SetEnabled(false);Set(window,"render",true);NoNative(window);
  state=Fixture();root=Build(window,state);Click(Tagged<Button>(root,"sideKeyLeftForward"));draft=Draft(window);draft.Target="MouseClickRight";draft.Dirty=true;var saved=(MouseButtonsDraft)Call(window,"CaptureMouseButtonsState");Check(!Object.ReferenceEquals(saved,draft)&&saved.Target==draft.Target,"capture clones only data");var json=new JavaScriptSerializer();string data=json.Serialize(saved);Check(!data.Contains("Observed")&&!data.Contains("Reference")&&!data.Contains("Permission")&&!data.Contains("Worker"),"preview draft carries no references, permission or worker handles");saved=json.Deserialize<MouseButtonsDraft>(data);Call(window,"RestoreMouseButtonsState",saved);draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",state);Check(draft.Target=="MouseClickRight"&&draft.SelectedButton=="sideKeyLeftForward"&&(bool)Field(window,"mouseButtonsWaitingForRead"),"replacement preserves local selection while cached snapshot is blocked");Check(!(bool)Call(window,"MouseButtonsHasPendingDraft",state),"restored waiting draft does not suppress fresh GET");Check(!(bool)Call(window,"MouseButtonsCanEdit",state,draft),"restoration cannot revive old session edit permission");
  var fresh=Copy(state);States(window)["mouse"]=fresh;draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",fresh);Check(draft.Target=="MouseClickRight"&&draft.Dirty&&!(bool)Field(window,"mouseButtonsWaitingForRead"),"new complete reference unlocks even with same-second capturedAt");Check((bool)Call(window,"MouseButtonsCanEdit",fresh,draft),"new fresh binding establishes a local edit baseline");
  var other=Fixture();other["deviceId"]="hid-fedcba9876543210";States(window)["mouse"]=other;draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",other);Check(draft.SelectedButton==""&&draft.Target==""&&!draft.Dirty,"device identity replacement discards old requested target");
  States(window).Clear();Call(window,"RestoreMouseButtonsState",saved);draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",null);Check(draft.SelectedButton==saved.SelectedButton&&draft.Target==saved.Target&&(bool)Field(window,"mouseButtonsWaitingForRead"),"restored local choices survive absent device snapshot");var firstFresh=Fixture();States(window)["mouse"]=firstFresh;draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",firstFresh);Check(draft.Target==saved.Target&&!(bool)Field(window,"mouseButtonsWaitingForRead"),"first full GET unlocks when there was no cached reference");
  var invalid=saved.Copy();invalid.SelectedButton="rawCode";Call(window,"RestoreMouseButtonsState",invalid);Check(Draft(window)==null,"invalid restored physical source discarded");invalid=saved.Copy();invalid.Target="Macro";Call(window,"RestoreMouseButtonsState",invalid);Check(Draft(window)==null,"unrecognized restored target discarded");invalid=saved.Copy();invalid.BaselineCode=-1;Call(window,"RestoreMouseButtonsState",invalid);Check(Draft(window)==null,"invalid restored native code discarded");NoNative(window);
 }
 static void LayoutCase(MainWindow window,Dictionary<string,object> state,int width,string selected,bool shift,string label,string output){
  States(window).Clear();if(state!=null)States(window)["mouse"]=state;Call(window,"RestoreMouseButtonsState",null);var draft=(MouseButtonsDraft)Call(window,"MouseButtonsValues",state);draft.SelectedButton=selected;draft.Shift=shift;Call(window,"MouseButtonsValues",state);
  ((Dictionary<string,string>)Field(window,"gearTabs"))["mouse"]="按键";Call(window,"ShowPage","device:mouse");var root=(FrameworkElement)window.Content;int height=width==1538?826:760;((ScrollViewer)Field(window,"pageScroll")).ScrollToTop();Measure(root,width,height);var surface=Tagged<Canvas>(root,"MouseButtons.Surface");
  Near(surface.Width,1246,"original full body width");Near(surface.TransformToAncestor(root).Transform(new Point()).Y,117,"integrated header/body origin");Near(surface.TransformToAncestor(root).Transform(new Point()).X,270,"body origin includes sidebar and 22 pixel page padding");var editor=Tagged<Border>(surface,"MouseButtons.Editor");Near(Canvas.GetLeft(editor),829,"right editor x");Near(Canvas.GetTop(editor),82,"right editor y");Near(editor.Width,376,"right editor width");Near(editor.Height,493,"right editor height");var figure=Tagged<FrameworkElement>(surface,"MouseButtons.Figure");Near(figure.Width,190,"mouse figure width");Near(figure.Height,362,"mouse figure height");Check(Tagged<Canvas>(figure,"MouseButtons.OwnGeometry").Width==190,"normal page uses an independently drawn diagram instead of a tiny photo canvas");Check(!Logical<Image>(surface).Any(),"page reads no manufacturer schematic or product images");
  string[] left={"leftButton","sideKeyLeftForward","sideKeyLeftBackward","scrollUp"},right={"middleButton","scrollDown","rightButton"};double[] leftY={146,241,334,428},rightY={193,287,382};for(int i=0;i<7;i++){string source=i<4?left[i]:right[i-4];var button=Tagged<Button>(surface,source);Near(Canvas.GetLeft(button),i<4?49:540,"physical label column");Near(Canvas.GetTop(button),i<4?leftY[i]:rightY[i-4],"physical label row");Near(button.Width,220,"physical label width");Near(button.Height,35,"physical label height");var observed=MouseButtonsUiFacts.Read(state,source,shift);Check(Convert.ToString(button.Content)==(observed.BindingKnown?MouseButtonsUiFacts.Caption(observed.Target):"—"),"label follows its current independent getter bank");}
  var reset=Tagged<Button>(surface,"MouseButtons.Reset");Check(!reset.IsEnabled,"Reset gains no unimplemented command");Near(Canvas.GetLeft(reset),1070,"reset original x");Near(Canvas.GetTop(reset),24,"reset original y");
  if(selected.Length==0){Check(Tagged<TextBlock>(surface,"MouseButtons.EmptyPrompt").Text=="选择一个鼠标按钮以编辑其设置。","exact original empty prompt");Check(!Logical<ComboBox>(editor).Any(),"empty editor has no invented parameter rows");}else{var title=Tagged<TextBlock>(surface,"MouseButtons.SelectedTitle");Check(title.Text==MouseButtonsUiFacts.Caption(selected),"title identifies selected physical source");var type=Tagged<ComboBox>(surface,"MouseButtons.Type");var functions=Tagged<ComboBox>(surface,"MouseButtons.Function");Near(Canvas.GetTop(type),84,"type dropdown original offset");Near(Canvas.GetTop(functions),219,"mouse function dropdown original offset");Check(type.Items.Cast<object>().Where(item=>Value(item)!="unknown").Select(Name).SequenceEqual(new[]{"鼠标功能","键盘功能","宏","多媒体","Windows 快捷方式","speed shift","开启 Armoury Crate","预设输入文字","截图"}),"nine observed category labels and order");Check(type.Items.Cast<object>().Where(item=>Value(item)!="mouse").All(item=>!Enabled(item)),"unsupported categories disabled");var expected=MouseButtonsUiFacts.MouseFunctions.Where(name=>MouseButtonsUiFacts.Options(state,"buttonTargets").Contains(name,StringComparer.Ordinal)).Select(MouseButtonsUiFacts.Caption);Check(functions.Items.Cast<object>().Where(Enabled).Select(Name).SequenceEqual(expected),"function list contains only original ten entries in order");Check(!Tagged<Button>(surface,"MouseButtons.Apply").IsEnabled,"render-only never enables hardware Apply");}
  foreach(var block in Logical<TextBlock>(surface)){if(block.ActualWidth<=0||block.ActualHeight<=0)continue;Check(block.TextTrimming!=TextTrimming.None||block.DesiredSize.Width-block.Margin.Left-block.Margin.Right<=block.ActualWidth+1,"text has no intrinsic clipping: "+block.Text);var bounds=block.TransformToAncestor(surface).TransformBounds(new Rect(0,0,block.ActualWidth,block.ActualHeight));Check(bounds.Left>=-1&&bounds.Right<=surface.Width+1,"text fits original body canvas: "+block.Text);}
  if(output!=null)Save(root,width,height,output,label+"-"+width+".png");var viewport=Tagged<ScrollViewer>(surface.Parent as DependencyObject??root,"MouseButtons.Viewport");viewport.ScrollToRightEnd();((ScrollViewer)Field(window,"pageScroll")).ScrollToBottom();Pump(root);var boundsAfter=editor.TransformToAncestor(root).TransformBounds(new Rect(0,0,editor.ActualWidth,editor.ActualHeight));Check(boundsAfter.Right<=width-20+1&&boundsAfter.Left>=248,"entire editor reachable at both widths");Check(boundsAfter.Bottom<=height-20+1,"editor bottom reachable by page scrolling");NoNative(window);layouts++;
 }
 static void Save(FrameworkElement root,int width,int height,string output,string file){var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(Path.Combine(output,file)))encoder.Save(stream);}
 [STAThread] public static int Main(string[] args){try{Run(args);return 0;}catch(Exception error){for(var current=error;current!=null;current=current.InnerException)Console.Error.WriteLine(current.GetType().Name+": "+current.Message+"\n"+current.StackTrace);return 1;}}
 static void Run(string[] args){new Application();string output=args.Length==2&&args[0]=="--render"?Path.GetFullPath(args[1]):null;if(output!=null)Directory.CreateDirectory(output);Facts();var window=new MainWindow(true);DraftsAndGates(window);var unknown=Fixture();Snapshot(unknown)["buttonBindings"]=null;var offline=Fixture();offline["online"]=false;var zero=Fixture();Binding(zero,"sideKeyLeftForward")["targetCode"]=0;Binding(zero,"sideKeyLeftForward")["target"]=null;var fixtures=new[]{Fixture(),unknown,offline,zero,null};foreach(int width in new[]{1538,1180}){LayoutCase(window,Fixture(),width,"",false,"empty",output);for(int index=0;index<fixtures.Length;index++)LayoutCase(window,fixtures[index],width,"sideKeyLeftForward",false,"fixture-"+index,output);LayoutCase(window,Fixture(),width,"sideKeyLeftForward",true,"shift",output);LayoutCase(window,Fixture(),width,"dpi1",false,"dpi",output);}Console.WriteLine("Mouse buttons: "+checks+" checks, "+layouts+" unshown layouts; native/GET/SET=0.");}
